import XCTest
@testable import SahkoCore
final class ClassifierTests: XCTestCase {
 func testBriefReferenceAndMusicSwitchesDoNotDrift() { var c=Classifier();let p=Policy();XCTAssertEqual(c.classify(.init(app:"Figma"),policy:p,now:0).state,.focused);XCTAssertEqual(c.classify(.init(app:"Spotify",audioContext:true),policy:p,now:20).state,.focused);XCTAssertEqual(c.classify(.init(app:"Figma"),policy:p,now:40).state,.focused) }
 func testContinuousOffTaskThresholdResetsOnReturningToWork() { var c=Classifier();let p=Policy();_ = c.classify(.init(app:"Chrome",host:"reddit.com"),policy:p,now:0);XCTAssertEqual(c.classify(.init(app:"Chrome",host:"reddit.com"),policy:p,now:89).state,.focused);XCTAssertEqual(c.classify(.init(app:"Chrome",host:"reddit.com"),policy:p,now:91).state,.drifting);_ = c.classify(.init(app:"Figma"),policy:p,now:92);XCTAssertEqual(c.classify(.init(app:"Chrome",host:"reddit.com"),policy:p,now:100).state,.focused) }
 func testSpotifyNeverExemptsRedditAndIdleNeverExemptsDeepWork() { var c=Classifier();let p=Policy();_ = c.classify(.init(app:"Chrome",host:"reddit.com",audioContext:true),policy:p,now:0);XCTAssertEqual(c.classify(.init(app:"Chrome",host:"reddit.com",audioContext:true),policy:p,now:91).state,.drifting);XCTAssertEqual(c.classify(.init(app:"Figma",idle:181),policy:p,now:92).state,.drifting) }
 func testReadingIdleAndCustomBuckets() { var c=Classifier();var p=Policy();p.idleSeconds=900;p.distracting=["Games"];XCTAssertEqual(c.classify(.init(app:"Preview",idle:500),policy:p,now:0).state,.focused);_ = c.classify(.init(app:"Games"),policy:p,now:10);XCTAssertEqual(c.classify(.init(app:"Games"),policy:p,now:101).state,.drifting);XCTAssertEqual(c.classify(.init(app:"Games",onBreak:true),policy:p,now:200).state,.resting) }
 func testWirePayloadHasNoRawContextFields() throws { let data=try JSONEncoder().encode(SharedSnapshot());let keys=Set((try JSONSerialization.jsonObject(with:data) as! [String:Any]).keys);XCTAssertFalse(keys.contains("url"));XCTAssertFalse(keys.contains("windowTitle"));XCTAssertFalse(keys.contains("app"));XCTAssertTrue(keys.contains("state")) }
}
